static loomc_status_t deepseek_make_status(loomc_status_code_t code,
                                           const char* file, uint32_t line,
                                           const char* format, ...) {
  va_list varargs;
  va_start(varargs, format);
  va_list varargs_copy;
  va_copy(varargs_copy, varargs);
  const int required_length = vsnprintf(NULL, 0, format, varargs);
  va_end(varargs);
  if (required_length < 0) {
    va_end(varargs_copy);
    return loomc_status_from_code(code);
  }
  char* buffer = (char*)malloc((size_t)required_length + 1);
  if (buffer == NULL) {
    va_end(varargs_copy);
    return loomc_status_from_code(code);
  }
  const int written =
      vsnprintf(buffer, (size_t)required_length + 1, format, varargs_copy);
  va_end(varargs_copy);
  if (written < 0) {
    free(buffer);
    return loomc_status_from_code(code);
  }
  loomc_status_t status = loomc_status_allocate(
      code, file, line, loomc_make_string_view(buffer, (size_t)written));
  free(buffer);
  return status;
}

#define DEEPSEEK_STATUS(code, ...) \
  deepseek_make_status((code), __FILE__, __LINE__, __VA_ARGS__)

static bool write_protocol_linef(FILE* file, const char* format, ...);

static char* format_status_alloc(loomc_status_t status,
                                 size_t* out_formatted_length) {
  *out_formatted_length = 0;
  loomc_host_size_t required_length = 0;
  (void)loomc_status_format(status, 0, NULL, &required_length);
  if (required_length >= SIZE_MAX) return NULL;
  char* buffer = (char*)malloc((size_t)required_length + 1);
  if (buffer == NULL) return NULL;
  loomc_host_size_t written_length = 0;
  if (!loomc_status_format(status, required_length + 1, buffer,
                           &written_length) ||
      written_length > required_length) {
    free(buffer);
    return NULL;
  }
  buffer[written_length] = '\0';
  *out_formatted_length = (size_t)written_length;
  return buffer;
}

static void print_status(loomc_status_t status) {
  size_t formatted_length = 0;
  char* buffer = format_status_alloc(status, &formatted_length);
  if (buffer != NULL) {
    (void)fwrite(buffer, 1, formatted_length, stderr);
    fputc('\n', stderr);
    free(buffer);
  } else {
    const char* code = loomc_status_code_string(loomc_status_code(status));
    fprintf(stderr, "%s\n", code != NULL ? code : "UNKNOWN");
  }
}

static void print_result_diagnostics(const loomc_result_t* result) {
  for (loomc_host_size_t i = 0; i < loomc_result_diagnostic_count(result);
       ++i) {
    const loomc_diagnostic_t* diagnostic =
        loomc_result_diagnostic_at(result, i);
    if (diagnostic == NULL) continue;
    fprintf(stderr, "%.*s: %.*s\n", (int)diagnostic->code.size,
            diagnostic->code.data, (int)diagnostic->message.size,
            diagnostic->message.data);
  }
}

static loomc_status_t require_successful_result(const loomc_result_t* result,
                                                const char* message) {
  if (result != NULL && loomc_result_succeeded(result)) {
    return loomc_ok_status();
  }
  if (result != NULL) print_result_diagnostics(result);
  return loomc_make_status(LOOMC_STATUS_FAILED_PRECONDITION, message);
}

static const loomc_artifact_t* find_result_artifact(
    const loomc_result_t* result, loomc_artifact_kind_t kind,
    loomc_string_view_t format) {
  if (result == NULL) return NULL;
  for (loomc_host_size_t i = 0; i < loomc_result_artifact_count(result); ++i) {
    const loomc_artifact_t* artifact = loomc_result_artifact_at(result, i);
    if (artifact != NULL && artifact->kind == kind &&
        loomc_string_view_equal(artifact->format, format)) {
      return artifact;
    }
  }
  return NULL;
}

static char* make_path2(const char* directory, const char* leaf) {
  const size_t directory_length = strlen(directory);
  const size_t leaf_length = strlen(leaf);
  const bool needs_separator =
      directory_length != 0 && directory[directory_length - 1] != '/' &&
      directory[directory_length - 1] != '\\';
  if (directory_length > SIZE_MAX - leaf_length - 2) return NULL;
  char* path =
      (char*)malloc(directory_length + (needs_separator ? 1 : 0) + leaf_length +
                    1);
  if (path == NULL) return NULL;
  memcpy(path, directory, directory_length);
  size_t offset = directory_length;
  if (needs_separator) path[offset++] = '/';
  memcpy(path + offset, leaf, leaf_length);
  path[offset + leaf_length] = '\0';
  return path;
}

static char* path_directory_copy(const char* path) {
  const char* slash = strrchr(path, '/');
  const char* backslash = strrchr(path, '\\');
  const char* separator = slash;
  if (separator == NULL ||
      (backslash != NULL && backslash > separator)) {
    separator = backslash;
  }
  if (separator == NULL) {
    char* directory = (char*)malloc(2u);
    if (directory != NULL) memcpy(directory, ".", 2u);
    return directory;
  }
  const size_t length = separator == path ? 1u : (size_t)(separator - path);
  char* directory = (char*)malloc(length + 1u);
  if (directory == NULL) return NULL;
  memcpy(directory, path, length);
  directory[length] = '\0';
  return directory;
}

static bool path_is_simple_leaf(const char* path) {
  return path[0] != '\0' && strcmp(path, ".") != 0 &&
         strcmp(path, "..") != 0 && strchr(path, '/') == NULL &&
         strchr(path, '\\') == NULL;
}

static char* duplicate_cstring(const char* value) {
  const size_t length = strlen(value);
  char* result = (char*)malloc(length + 1);
  if (result != NULL) memcpy(result, value, length + 1);
  return result;
}

static bool string_ends_with(const char* value, const char* suffix) {
  const size_t value_length = strlen(value);
  const size_t suffix_length = strlen(suffix);
  return value_length >= suffix_length &&
         memcmp(value + value_length - suffix_length, suffix, suffix_length) ==
             0;
}

static loomc_status_t source_format_from_path(
    const char* path, loomc_source_format_t* out_format) {
  if (string_ends_with(path, ".loom")) {
    *out_format = LOOMC_SOURCE_FORMAT_TEXT;
    return loomc_ok_status();
  }
  if (string_ends_with(path, ".loombc")) {
    *out_format = LOOMC_SOURCE_FORMAT_BYTECODE;
    return loomc_ok_status();
  }
  return DEEPSEEK_STATUS(LOOMC_STATUS_INVALID_ARGUMENT,
                         "kernel source must end in .loom or .loombc: %s",
                         path);
}

static int deepseek_file_seek(FILE* file, int64_t offset, int origin) {
#if defined(_WIN32)
  return _fseeki64(file, offset, origin);
#else
  return fseeko(file, (off_t)offset, origin);
#endif
}

static int64_t deepseek_file_tell(FILE* file) {
#if defined(_WIN32)
  return _ftelli64(file);
#else
  return (int64_t)ftello(file);
#endif
}

static loomc_status_t query_file_size(FILE* file, const char* path,
                                      uint64_t* out_size) {
  if (deepseek_file_seek(file, 0, SEEK_END) != 0) {
    return DEEPSEEK_STATUS(LOOMC_STATUS_DATA_LOSS,
                           "failed to seek %s: %s", path, strerror(errno));
  }
  const int64_t length = deepseek_file_tell(file);
  if (length < 0) {
    return DEEPSEEK_STATUS(LOOMC_STATUS_DATA_LOSS,
                           "failed to determine size of %s: %s", path,
                           strerror(errno));
  }
  if (deepseek_file_seek(file, 0, SEEK_SET) != 0) {
    return DEEPSEEK_STATUS(LOOMC_STATUS_DATA_LOSS,
                           "failed to rewind %s: %s", path, strerror(errno));
  }
  *out_size = (uint64_t)length;
  return loomc_ok_status();
}

static loomc_status_t read_entire_file(const char* path, uint8_t** out_data,
                                       size_t* out_length) {
  *out_data = NULL;
  *out_length = 0;
  FILE* file = fopen(path, "rb");
  if (file == NULL) {
    return DEEPSEEK_STATUS(LOOMC_STATUS_NOT_FOUND, "failed to open %s: %s",
                           path, strerror(errno));
  }
  uint64_t file_size = 0;
  loomc_status_t status = query_file_size(file, path, &file_size);
  if (loomc_status_is_ok(status) && file_size > SIZE_MAX - 1) {
    status = DEEPSEEK_STATUS(LOOMC_STATUS_RESOURCE_EXHAUSTED,
                             "%s is too large for this process", path);
  }
  uint8_t* data = NULL;
  if (loomc_status_is_ok(status)) {
    data = (uint8_t*)malloc((size_t)file_size + 1);
    if (data == NULL) {
      status = DEEPSEEK_STATUS(LOOMC_STATUS_RESOURCE_EXHAUSTED,
                               "failed to allocate %" PRIu64
                               " bytes while reading %s",
                               file_size + 1, path);
    }
  }
  if (loomc_status_is_ok(status) && file_size != 0) {
    const size_t read_length = fread(data, 1, (size_t)file_size, file);
    if (read_length != (size_t)file_size) {
      status = DEEPSEEK_STATUS(
          LOOMC_STATUS_DATA_LOSS,
          "short read from %s: expected %" PRIu64 " bytes, got %zu", path,
          file_size, read_length);
    }
  }
  if (fclose(file) != 0 && loomc_status_is_ok(status)) {
    status = DEEPSEEK_STATUS(LOOMC_STATUS_DATA_LOSS,
                             "failed to close %s: %s", path, strerror(errno));
  }
  if (!loomc_status_is_ok(status)) {
    free(data);
    return status;
  }
  data[file_size] = 0;
  *out_data = data;
  *out_length = (size_t)file_size;
  return loomc_ok_status();
}

// Minimal, strict JSON tokenizer. Tokens point into an owned byte buffer and
// preserve parent links, which is enough for the three preparation manifests
// and the emitted artifact manifest without bringing a private parser API into
// this example.
typedef enum json_token_type_e {
  JSON_TOKEN_OBJECT,
  JSON_TOKEN_ARRAY,
  JSON_TOKEN_STRING,
  JSON_TOKEN_PRIMITIVE,
} json_token_type_t;

typedef struct json_token_t {
  json_token_type_t type;
  size_t start;
  size_t end;
  int32_t parent;
  uint32_t size;
} json_token_t;

typedef struct json_document_t {
  uint8_t* data;
  size_t length;
  json_token_t* tokens;
  size_t token_count;
  size_t token_capacity;
  char error[256];
} json_document_t;

typedef struct json_parser_t {
  json_document_t* document;
  size_t position;
  uint32_t depth;
} json_parser_t;

static void json_document_deinitialize(json_document_t* document) {
  free(document->tokens);
  free(document->data);
  memset(document, 0, sizeof(*document));
}

static void json_set_error(json_parser_t* parser, const char* format, ...) {
  if (parser->document->error[0] != '\0') return;
  va_list varargs;
  va_start(varargs, format);
  vsnprintf(parser->document->error, sizeof(parser->document->error), format,
            varargs);
  va_end(varargs);
}

static void json_skip_whitespace(json_parser_t* parser) {
  while (parser->position < parser->document->length) {
    const uint8_t c = parser->document->data[parser->position];
    if (c != ' ' && c != '\t' && c != '\r' && c != '\n') break;
    ++parser->position;
  }
}

static int32_t json_add_token(json_parser_t* parser, json_token_type_t type,
                              size_t start, int32_t parent) {
  json_document_t* document = parser->document;
  if (document->token_count == document->token_capacity) {
    size_t new_capacity =
        document->token_capacity == 0 ? 256 : document->token_capacity * 2;
    if (new_capacity < document->token_capacity ||
        new_capacity > SIZE_MAX / sizeof(json_token_t)) {
      json_set_error(parser, "JSON token count overflow");
      return -1;
    }
    json_token_t* new_tokens = (json_token_t*)realloc(
        document->tokens, new_capacity * sizeof(json_token_t));
    if (new_tokens == NULL) {
      json_set_error(parser, "out of memory tokenizing JSON");
      return -1;
    }
    document->tokens = new_tokens;
    document->token_capacity = new_capacity;
  }
  if (document->token_count > INT32_MAX) {
    json_set_error(parser, "too many JSON tokens");
    return -1;
  }
  const int32_t index = (int32_t)document->token_count++;
  document->tokens[index] = (json_token_t){
      .type = type,
      .start = start,
      .end = start,
      .parent = parent,
      .size = 0,
  };
  return index;
}

static bool json_parse_value(json_parser_t* parser, int32_t parent,
                             int32_t* out_index);

static bool json_parse_string(json_parser_t* parser, int32_t parent,
                              int32_t* out_index) {
  const size_t quote = parser->position;
  if (parser->document->data[quote] != '"') return false;
  const int32_t token_index =
      json_add_token(parser, JSON_TOKEN_STRING, quote + 1, parent);
  if (token_index < 0) return false;
  ++parser->position;
  while (parser->position < parser->document->length) {
    const uint8_t c = parser->document->data[parser->position++];
    if (c == '"') {
      parser->document->tokens[token_index].end = parser->position - 1;
      *out_index = token_index;
      return true;
    }
    if (c < 0x20) {
      json_set_error(parser, "unescaped control byte at offset %zu",
                     parser->position - 1);
      return false;
    }
    if (c != '\\') continue;
    if (parser->position >= parser->document->length) {
      json_set_error(parser, "truncated JSON escape");
      return false;
    }
    const uint8_t escaped = parser->document->data[parser->position++];
    if (escaped == 'u') {
      if (parser->position + 4 > parser->document->length) {
        json_set_error(parser, "truncated JSON Unicode escape");
        return false;
      }
      for (size_t i = 0; i < 4; ++i) {
        const uint8_t h = parser->document->data[parser->position + i];
        if (!((h >= '0' && h <= '9') || (h >= 'a' && h <= 'f') ||
              (h >= 'A' && h <= 'F'))) {
          json_set_error(parser, "invalid JSON Unicode escape");
          return false;
        }
      }
      parser->position += 4;
    } else if (strchr("\"\\/bfnrt", escaped) == NULL) {
      json_set_error(parser, "invalid JSON escape at offset %zu",
                     parser->position - 1);
      return false;
    }
  }
  json_set_error(parser, "unterminated JSON string at offset %zu", quote);
  return false;
}

static bool json_parse_object(json_parser_t* parser, int32_t parent,
                              int32_t* out_index) {
  const size_t start = parser->position;
  const int32_t object_index =
      json_add_token(parser, JSON_TOKEN_OBJECT, start, parent);
  if (object_index < 0) return false;
  ++parser->position;
  json_skip_whitespace(parser);
  if (parser->position < parser->document->length &&
      parser->document->data[parser->position] == '}') {
    parser->document->tokens[object_index].end = ++parser->position;
    *out_index = object_index;
    return true;
  }
  for (;;) {
    json_skip_whitespace(parser);
    int32_t key_index = -1;
    if (parser->position >= parser->document->length ||
        !json_parse_string(parser, object_index, &key_index)) {
      if (parser->document->error[0] == '\0') {
        json_set_error(parser, "expected object key at offset %zu",
                       parser->position);
      }
      return false;
    }
    json_skip_whitespace(parser);
    if (parser->position >= parser->document->length ||
        parser->document->data[parser->position] != ':') {
      json_set_error(parser, "expected ':' after object key");
      return false;
    }
    ++parser->position;
    json_skip_whitespace(parser);
    int32_t value_index = -1;
    if (!json_parse_value(parser, object_index, &value_index)) return false;
    ++parser->document->tokens[object_index].size;
    json_skip_whitespace(parser);
    if (parser->position >= parser->document->length) {
      json_set_error(parser, "unterminated JSON object");
      return false;
    }
    const uint8_t delimiter = parser->document->data[parser->position++];
    if (delimiter == '}') {
      parser->document->tokens[object_index].end = parser->position;
      *out_index = object_index;
      return true;
    }
    if (delimiter != ',') {
      json_set_error(parser, "expected ',' or '}' in object");
      return false;
    }
  }
}

static bool json_parse_array(json_parser_t* parser, int32_t parent,
                             int32_t* out_index) {
  const size_t start = parser->position;
  const int32_t array_index =
      json_add_token(parser, JSON_TOKEN_ARRAY, start, parent);
  if (array_index < 0) return false;
  ++parser->position;
  json_skip_whitespace(parser);
  if (parser->position < parser->document->length &&
      parser->document->data[parser->position] == ']') {
    parser->document->tokens[array_index].end = ++parser->position;
    *out_index = array_index;
    return true;
  }
  for (;;) {
    json_skip_whitespace(parser);
    int32_t value_index = -1;
    if (!json_parse_value(parser, array_index, &value_index)) return false;
    ++parser->document->tokens[array_index].size;
    json_skip_whitespace(parser);
    if (parser->position >= parser->document->length) {
      json_set_error(parser, "unterminated JSON array");
      return false;
    }
    const uint8_t delimiter = parser->document->data[parser->position++];
    if (delimiter == ']') {
      parser->document->tokens[array_index].end = parser->position;
      *out_index = array_index;
      return true;
    }
    if (delimiter != ',') {
      json_set_error(parser, "expected ',' or ']' in array");
      return false;
    }
  }
}

static bool json_parse_primitive(json_parser_t* parser, int32_t parent,
                                 int32_t* out_index) {
  const size_t start = parser->position;
  while (parser->position < parser->document->length) {
    const uint8_t c = parser->document->data[parser->position];
    if (c == ',' || c == ']' || c == '}' || c == ' ' || c == '\t' ||
        c == '\r' || c == '\n') {
      break;
    }
    if (c < 0x20 || c == '"' || c == '[' || c == '{' || c == ':') {
      json_set_error(parser, "invalid primitive byte at offset %zu",
                     parser->position);
      return false;
    }
    ++parser->position;
  }
  if (parser->position == start) {
    json_set_error(parser, "expected JSON value at offset %zu", start);
    return false;
  }
  const int32_t token_index =
      json_add_token(parser, JSON_TOKEN_PRIMITIVE, start, parent);
  if (token_index < 0) return false;
  parser->document->tokens[token_index].end = parser->position;
  *out_index = token_index;
  return true;
}

static bool json_parse_value(json_parser_t* parser, int32_t parent,
                             int32_t* out_index) {
  if (++parser->depth > 128) {
    json_set_error(parser, "JSON nesting exceeds 128 levels");
    return false;
  }
  if (parser->position >= parser->document->length) {
    json_set_error(parser, "expected JSON value at end of input");
    --parser->depth;
    return false;
  }
  bool result = false;
  switch (parser->document->data[parser->position]) {
    case '{':
      result = json_parse_object(parser, parent, out_index);
      break;
    case '[':
      result = json_parse_array(parser, parent, out_index);
      break;
    case '"':
      result = json_parse_string(parser, parent, out_index);
      break;
    default:
      result = json_parse_primitive(parser, parent, out_index);
      break;
  }
  --parser->depth;
  return result;
}

static loomc_status_t json_document_parse_bytes(const uint8_t* data,
                                                size_t length,
                                                const char* description,
                                                json_document_t* out_document) {
  memset(out_document, 0, sizeof(*out_document));
  out_document->data = (uint8_t*)malloc(length + 1);
  if (out_document->data == NULL) {
    return DEEPSEEK_STATUS(LOOMC_STATUS_RESOURCE_EXHAUSTED,
                           "failed to allocate JSON buffer for %s",
                           description);
  }
  memcpy(out_document->data, data, length);
  out_document->data[length] = 0;
  out_document->length = length;
  json_parser_t parser = {
      .document = out_document,
  };
  json_skip_whitespace(&parser);
  int32_t root_index = -1;
  if (!json_parse_value(&parser, -1, &root_index)) {
    loomc_status_t status =
        DEEPSEEK_STATUS(LOOMC_STATUS_INVALID_ARGUMENT,
                        "invalid JSON in %s: %s", description,
                        out_document->error[0] != '\0' ? out_document->error
                                                       : "unknown parse error");
    json_document_deinitialize(out_document);
    return status;
  }
  json_skip_whitespace(&parser);
  if (parser.position != length || root_index != 0) {
    loomc_status_t status = DEEPSEEK_STATUS(
        LOOMC_STATUS_INVALID_ARGUMENT,
        "invalid JSON in %s: trailing content at offset %zu", description,
        parser.position);
    json_document_deinitialize(out_document);
    return status;
  }
  return loomc_ok_status();
}

static loomc_status_t json_document_load(const char* path,
                                         json_document_t* out_document) {
  uint8_t* data = NULL;
  size_t length = 0;
  LOOMC_RETURN_IF_ERROR(read_entire_file(path, &data, &length));
  loomc_status_t status =
      json_document_parse_bytes(data, length, path, out_document);
  free(data);
  return status;
}

static bool json_token_string_equal(const json_document_t* document,
                                    int32_t token_index, const char* value) {
  if (token_index < 0 ||
      document->tokens[token_index].type != JSON_TOKEN_STRING) {
    return false;
  }
  const json_token_t* token = &document->tokens[token_index];
  const size_t length = token->end - token->start;
  return strlen(value) == length &&
         memcmp(document->data + token->start, value, length) == 0;
}

static int32_t json_object_get(const json_document_t* document,
                               int32_t object_index, const char* key) {
  if (object_index < 0 ||
      document->tokens[object_index].type != JSON_TOKEN_OBJECT) {
    return -1;
  }
  const json_token_t* object = &document->tokens[object_index];
  for (size_t i = (size_t)object_index + 1; i < document->token_count &&
                                                  document->tokens[i].start <
                                                      object->end;
       ++i) {
    if (document->tokens[i].parent != object_index ||
        document->tokens[i].type != JSON_TOKEN_STRING) {
      continue;
    }
    size_t value_index = i + 1;
    while (value_index < document->token_count &&
           document->tokens[value_index].parent != object_index) {
      ++value_index;
    }
    if (value_index >= document->token_count) return -1;
    if (json_token_string_equal(document, (int32_t)i, key)) {
      return (int32_t)value_index;
    }
    i = value_index;
  }
  return -1;
}

static bool json_snapshot_metadata_equal(const json_document_t* document,
                                         int32_t root_index) {
  const int32_t metadata =
      json_object_get(document, root_index, "snapshot_metadata_sha256");
  return metadata >= 0 &&
         document->tokens[metadata].type == JSON_TOKEN_OBJECT &&
         json_token_string_equal(
             document, json_object_get(document, metadata, "config.json"),
             DEEPSEEK_CONFIG_SHA256) &&
         json_token_string_equal(
             document,
             json_object_get(document, metadata, "generation_config.json"),
             DEEPSEEK_GENERATION_CONFIG_SHA256) &&
         json_token_string_equal(
             document, json_object_get(document, metadata, "tokenizer.json"),
             DEEPSEEK_TOKENIZER_SHA256) &&
         json_token_string_equal(
             document,
             json_object_get(document, metadata, "tokenizer_config.json"),
             DEEPSEEK_TOKENIZER_CONFIG_SHA256);
}

static int32_t json_array_at(const json_document_t* document,
                             int32_t array_index, uint32_t element_index) {
  if (array_index < 0 ||
      document->tokens[array_index].type != JSON_TOKEN_ARRAY) {
    return -1;
  }
  const json_token_t* array = &document->tokens[array_index];
  uint32_t seen = 0;
  for (size_t i = (size_t)array_index + 1; i < document->token_count &&
                                                 document->tokens[i].start <
                                                     array->end;
       ++i) {
    if (document->tokens[i].parent != array_index) continue;
    if (seen++ == element_index) return (int32_t)i;
  }
  return -1;
}

static bool json_token_is_null(const json_document_t* document,
                               int32_t token_index) {
  if (token_index < 0 ||
      document->tokens[token_index].type != JSON_TOKEN_PRIMITIVE) {
    return false;
  }
  const json_token_t* token = &document->tokens[token_index];
  return token->end - token->start == 4 &&
         memcmp(document->data + token->start, "null", 4) == 0;
}

static bool json_token_u64(const json_document_t* document, int32_t token_index,
                           uint64_t* out_value) {
  if (token_index < 0 ||
      document->tokens[token_index].type != JSON_TOKEN_PRIMITIVE) {
    return false;
  }
  const json_token_t* token = &document->tokens[token_index];
  const size_t length = token->end - token->start;
  if (length == 0 || length >= 64) return false;
  char buffer[64];
  memcpy(buffer, document->data + token->start, length);
  buffer[length] = '\0';
  if (buffer[0] == '-') return false;
  errno = 0;
  char* end = NULL;
  const uint64_t value = strtoull(buffer, &end, 10);
  if (errno != 0 || end == NULL || *end != '\0') return false;
  *out_value = value;
  return true;
}

static bool json_token_i64(const json_document_t* document, int32_t token_index,
                           int64_t* out_value) {
  if (token_index < 0 ||
      document->tokens[token_index].type != JSON_TOKEN_PRIMITIVE) {
    return false;
  }
  const json_token_t* token = &document->tokens[token_index];
  const size_t length = token->end - token->start;
  if (length == 0 || length >= 64) return false;
  char buffer[64];
  memcpy(buffer, document->data + token->start, length);
  buffer[length] = '\0';
  errno = 0;
  char* end = NULL;
  const int64_t value = strtoll(buffer, &end, 10);
  if (errno != 0 || end == NULL || *end != '\0') return false;
  *out_value = value;
  return true;
}

static bool json_token_float(const json_document_t* document,
                             int32_t token_index, float* out_value) {
  if (token_index < 0 ||
      document->tokens[token_index].type != JSON_TOKEN_PRIMITIVE) {
    return false;
  }
  const json_token_t* token = &document->tokens[token_index];
  const size_t length = token->end - token->start;
  if (length == 0 || length >= 64) return false;
  char buffer[64];
  memcpy(buffer, document->data + token->start, length);
  buffer[length] = '\0';
  errno = 0;
  char* end = NULL;
  const float value = strtof(buffer, &end);
  if (errno != 0 || end == NULL || *end != '\0' || !isfinite(value)) {
    return false;
  }
  *out_value = value;
  return true;
}

static bool json_token_bool(const json_document_t* document,
                            int32_t token_index, bool expected) {
  if (token_index < 0 ||
      document->tokens[token_index].type != JSON_TOKEN_PRIMITIVE) {
    return false;
  }
  const json_token_t* token = &document->tokens[token_index];
  const char* spelling = expected ? "true" : "false";
  const size_t length = expected ? 4u : 5u;
  return token->end - token->start == length &&
         memcmp(document->data + token->start, spelling, length) == 0;
}

static int hex_value(uint8_t c) {
  if (c >= '0' && c <= '9') return c - '0';
  if (c >= 'a' && c <= 'f') return c - 'a' + 10;
  if (c >= 'A' && c <= 'F') return c - 'A' + 10;
  return -1;
}

static bool json_token_f32_record(const json_document_t* document,
                                  int32_t object_index, float* out_value) {
  if (object_index < 0 ||
      document->tokens[object_index].type != JSON_TOKEN_OBJECT) {
    return false;
  }
  float value = 0.0f;
  const int32_t hexadecimal =
      json_object_get(document, object_index, "hex");
  const int32_t little_endian_hex =
      json_object_get(document, object_index, "f32_le_hex");
  if (!json_token_float(document,
                        json_object_get(document, object_index, "value"),
                        &value) ||
      hexadecimal < 0 ||
      document->tokens[hexadecimal].type != JSON_TOKEN_STRING ||
      document->tokens[hexadecimal].end ==
          document->tokens[hexadecimal].start ||
      little_endian_hex < 0 ||
      document->tokens[little_endian_hex].type != JSON_TOKEN_STRING) {
    return false;
  }
  const json_token_t* hex_token = &document->tokens[little_endian_hex];
  if (hex_token->end - hex_token->start != 8u) return false;
  uint8_t bytes[4] = {0};
  for (size_t i = 0; i < 4u; ++i) {
    const int high = hex_value(document->data[hex_token->start + i * 2u]);
    const int low = hex_value(document->data[hex_token->start + i * 2u + 1u]);
    if (high < 0 || low < 0) return false;
    bytes[i] = (uint8_t)((high << 4) | low);
  }
  const uint32_t expected_bits =
      (uint32_t)bytes[0] | ((uint32_t)bytes[1] << 8u) |
      ((uint32_t)bytes[2] << 16u) | ((uint32_t)bytes[3] << 24u);
  uint32_t actual_bits = 0u;
  memcpy(&actual_bits, &value, sizeof(actual_bits));
  if (actual_bits != expected_bits) return false;
  *out_value = value;
  return true;
}

static bool append_utf8(uint32_t codepoint, char* output, size_t capacity,
                        size_t* inout_length) {
  uint8_t encoded[4];
  size_t count = 0;
  if (codepoint <= 0x7F) {
    encoded[count++] = (uint8_t)codepoint;
  } else if (codepoint <= 0x7FF) {
    encoded[count++] = (uint8_t)(0xC0 | (codepoint >> 6));
    encoded[count++] = (uint8_t)(0x80 | (codepoint & 0x3F));
  } else if (codepoint <= 0xFFFF) {
    encoded[count++] = (uint8_t)(0xE0 | (codepoint >> 12));
    encoded[count++] = (uint8_t)(0x80 | ((codepoint >> 6) & 0x3F));
    encoded[count++] = (uint8_t)(0x80 | (codepoint & 0x3F));
  } else if (codepoint <= 0x10FFFF) {
    encoded[count++] = (uint8_t)(0xF0 | (codepoint >> 18));
    encoded[count++] = (uint8_t)(0x80 | ((codepoint >> 12) & 0x3F));
    encoded[count++] = (uint8_t)(0x80 | ((codepoint >> 6) & 0x3F));
    encoded[count++] = (uint8_t)(0x80 | (codepoint & 0x3F));
  } else {
    return false;
  }
  if (*inout_length > capacity - count) return false;
  memcpy(output + *inout_length, encoded, count);
  *inout_length += count;
  return true;
}

static char* json_duplicate_string(const json_document_t* document,
                                   int32_t token_index) {
  if (token_index < 0 ||
      document->tokens[token_index].type != JSON_TOKEN_STRING) {
    return NULL;
  }
  const json_token_t* token = &document->tokens[token_index];
  const size_t raw_length = token->end - token->start;
  char* result = (char*)malloc(raw_length + 1);
  if (result == NULL) return NULL;
  size_t output_length = 0;
  for (size_t i = token->start; i < token->end;) {
    uint8_t c = document->data[i++];
    if (c != '\\') {
      result[output_length++] = (char)c;
      continue;
    }
    if (i >= token->end) {
      free(result);
      return NULL;
    }
    c = document->data[i++];
    switch (c) {
      case '"':
      case '\\':
      case '/':
        result[output_length++] = (char)c;
        break;
      case 'b':
        result[output_length++] = '\b';
        break;
      case 'f':
        result[output_length++] = '\f';
        break;
      case 'n':
        result[output_length++] = '\n';
        break;
      case 'r':
        result[output_length++] = '\r';
        break;
      case 't':
        result[output_length++] = '\t';
        break;
      case 'u': {
        if (i + 4 > token->end) {
          free(result);
          return NULL;
        }
        uint32_t codepoint = 0;
        for (size_t j = 0; j < 4; ++j) {
          const int value = hex_value(document->data[i++]);
          if (value < 0) {
            free(result);
            return NULL;
          }
          codepoint = (codepoint << 4) | (uint32_t)value;
        }
        if (codepoint >= 0xD800 && codepoint <= 0xDBFF) {
          if (i + 6 > token->end || document->data[i] != '\\' ||
              document->data[i + 1] != 'u') {
            free(result);
            return NULL;
          }
          i += 2;
          uint32_t low = 0;
          for (size_t j = 0; j < 4; ++j) {
            const int value = hex_value(document->data[i++]);
            if (value < 0) {
              free(result);
              return NULL;
            }
            low = (low << 4) | (uint32_t)value;
          }
          if (low < 0xDC00 || low > 0xDFFF) {
            free(result);
            return NULL;
          }
          codepoint =
              0x10000 + ((codepoint - 0xD800) << 10) + (low - 0xDC00);
        } else if (codepoint >= 0xDC00 && codepoint <= 0xDFFF) {
          free(result);
          return NULL;
        }
        if (!append_utf8(codepoint, result, raw_length, &output_length)) {
          free(result);
          return NULL;
        }
        break;
      }
      default:
        free(result);
        return NULL;
    }
  }
  result[output_length] = '\0';
  return result;
}

