typedef enum deepseek_experimental_mode_e {
  DEEPSEEK_EXPERIMENT_NONE = 0,
  DEEPSEEK_EXPERIMENT_LONG_KV_MIGRATION,
  DEEPSEEK_EXPERIMENT_LONG_CONTEXT_385,
  DEEPSEEK_EXPERIMENT_LONG_CONTEXT_API_384_PLUS_2,
  DEEPSEEK_EXPERIMENT_LONG_CONTEXT_STAGED,
  DEEPSEEK_EXPERIMENT_LONG_CONTEXT_131072,
  DEEPSEEK_EXPERIMENT_LONG_CONTEXT_131072_TILED,
  DEEPSEEK_EXPERIMENT_LONG_CONTEXT_131072_TILED_SERVING,
  DEEPSEEK_EXPERIMENT_LONG_CONTEXT_131072_TILED_Q512_SERVING,
  DEEPSEEK_EXPERIMENT_LONG_CONTEXT_131072_Q16K_AITER_SERVING,
  DEEPSEEK_EXPERIMENT_Q16K_DENSE_ASM_GATE,
} deepseek_experimental_mode_t;

